const LOCALES = { it: 'it-IT', en: 'en-US', es: 'es-ES', fr: 'fr-FR', de: 'de-DE' };
const WEEK_BASE = new Date(2024, 0, 1); // 2024-01-01 is a Monday
const WEEKDAY_ID_ORDER = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
const MON_SUN_ORDER = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

export function weekdayNarrow(locale) {
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(WEEK_BASE); d.setDate(WEEK_BASE.getDate() + i);
    return d.toLocaleDateString(locale, { weekday: 'narrow' });
  });
}
export function weekdayShort(locale) {
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(WEEK_BASE); d.setDate(WEEK_BASE.getDate() + i);
    return d.toLocaleDateString(locale, { weekday: 'short' });
  });
}
export function weekdayLongById(locale, id) {
  const idx = WEEKDAY_ID_ORDER.indexOf(id);
  if (idx < 0) return id;
  const d = new Date(WEEK_BASE); d.setDate(WEEK_BASE.getDate() + idx);
  return d.toLocaleDateString(locale, { weekday: 'long' });
}
export function weekdayShortById(locale, id) {
  const idx = WEEKDAY_ID_ORDER.indexOf(id);
  if (idx < 0) return id;
  const d = new Date(WEEK_BASE); d.setDate(WEEK_BASE.getDate() + idx);
  return d.toLocaleDateString(locale, { weekday: 'short' });
}
export function weekdayShortByMonSun(locale, id) {
  const idx = MON_SUN_ORDER.indexOf(id);
  if (idx < 0) return id;
  const d = new Date(WEEK_BASE); d.setDate(WEEK_BASE.getDate() + idx);
  return d.toLocaleDateString(locale, { weekday: 'short' });
}
