const I18nContext = createContext(null);

export function LanguageProvider({ children }) {
  const [lang, setLangState] = useState(() => localStorage.getItem(STORAGE_KEY) || DEFAULT_LANG);

  const setLang = useCallback((code) => {
    setLangState(code);
    try { localStorage.setItem(STORAGE_KEY, code); } catch (e) { /* ignore */ }
  }, []);

  const t = useCallback((key) => {
    const dict = DICT[lang] || DICT[DEFAULT_LANG];
    return dict[key] ?? DICT[DEFAULT_LANG][key] ?? key;
  }, [lang]);

  const locale = LOCALES[lang] || LOCALES[DEFAULT_LANG];

  const value = useMemo(() => ({ lang, setLang, t, locale }), [lang, setLang, t, locale]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error('useI18n must be used within LanguageProvider');
  return ctx;
}

export function useT() {
  return useI18n().t;
}